{
  "function": "() => {
  const ppos = document.querySelectorAll('input[name="pricePerOrder"]');
  const ups = document.querySelectorAll('input[name="unitPrice"]');
  const ums = document.querySelectorAll('select[name="unitMeasure"]');

  const results = [];

  [0, 1].forEach(idx => {
    // 1. pricePerOrder
    const ppo = ppos[idx];
    ppo.value = "22.99";
    ppo.dispatchEvent(new Event('input', { bubbles: true }));
    ppo.dispatchEvent(new Event('change', { bubbles: true }));

    // 2. unitPrice
    const up = ups[idx];
    up.value = "0.00";
    up.dispatchEvent(new Event('input', { bubbles: true }));
    up.dispatchEvent(new Event('change', { bubbles: true }));

    // 3. unitMeasure
    const um = ums[idx];
    um.selectedIndex = 0;
    if (um.options[0]) um.options[0].selected = true;
    if (um.options[1]) um.options[1].selected = false;
    um.value = "Per Item";
    um.dispatchEvent(new Event('input', { bubbles: true }));
    um.dispatchEvent(new Event('change', { bubbles: true }));

    // Check AUI select replacement if exists
    const auiPrompt = um.closest('.a-dropdown-container')?.querySelector('.a-dropdown-prompt');
    if (auiPrompt) {
      auiPrompt.innerText = "商品";
    }

    results.push({
      idx,
      pricePerOrder: ppo.value,
      unitPrice: up.value,
      unitMeasure: um.value
    });
  });

  return results;
}",
