  function findDeep(predicate, root = document) {
    let matches = [];
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
    let node = walker.nextNode();
    while (node) {
      if (predicate(node)) matches.push(node);
      if (node.shadowRoot) {
        matches = matches.concat(findDeep(predicate, node.shadowRoot));
      }
      node = walker.nextNode();
    }
    return matches;
  }

  const uploadElements = findDeep(el => {
    const text = el.innerText || el.getAttribute('label') || el.getAttribute('aria-label') || '';
    return text.includes('上传') || text.includes('Upload') || text.includes('附件') || el.tagName === 'INPUT' && el.type === 'file';
  });
  return uploadElements.map(el => ({
    tag: el.tagName,
    id: el.id,
