{"function":"async () => {
  const imgs = Array.from(document.querySelectorAll('img')).filter(i => i.src && i.src.includes('flow-content.google'));
  const results = [];

  for (let idx = 0; idx < imgs.length; idx++) {
    const img = imgs[idx];
    try {
      const resp = await fetch(img.src);
      const blob = await resp.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `voc_instructional_infographic_${idx + 1}.png`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      results.push({ index: idx + 1, downloaded: true, size: blob.size });
    } catch (e) {
      results.push({ index: idx + 1, downloaded: false, error: e.message });
    }
  }
  return results;
}","pageId":14,"toolSummary":"Trigger download for both generated images"}

