{"function":"() => {
  function findDeep(predicate, root = document) {
    let matches = [];
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
    let node = walker.nextNode();
    while (node) {
      if (predicate(node)) matches.push(node);
      if (node.shadowRoot) {
        matches = matches.concat(findDeep(predicate, node.shadowRoot));
      }
      node = walker.nextNode();
    }
    return matches;
  }

  const textareas = findDeep(el => el.tagName === 'TEXTAREA' || el.tagName === 'KAT-TEXTAREA');
  return textareas.map(el => ({
    tag: el.tagName,
    id: el.id,
    valueLength: (el.value || '').length,
    snippet: (el.value || '').slice(0, 80)
  }));
}","pageId":1,"toolSummary":"Verify pre-filled draft on Page 1"}

